17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.Collections;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.Map;
25	import java.util.Objects;
26	import java.util.stream.Collectors;
27	
28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.http.HttpHeaders;
31	import org.springframework.http.HttpStatus;
32	import org.springframework.http.ResponseEntity;
33	import org.springframework.security.core.Authentication;
34	import org.springframework.security.core.context.SecurityContextHolder;
35	import org.springframework.samples.petclinic.mapper.OwnerMapper;
36	import org.springframework.samples.petclinic.mapper.PetMapper;
37	import org.springframework.samples.petclinic.mapper.VisitMapper;
38	import org.springframework.samples.petclinic.model.Owner;
39	import org.springframework.samples.petclinic.model.Pet;
40	import org.springframework.samples.petclinic.model.Visit;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.service.ClinicService;
49	import org.springframework.security.access.prepost.PreAuthorize;
50	import org.springframework.web.bind.annotation.CrossOrigin;
51	import org.springframework.web.bind.annotation.RequestMapping;
52	import org.springframework.web.bind.annotation.RestController;
53	import org.springframework.web.util.UriComponentsBuilder;
54	
55	import jakarta.transaction.Transactional;
56	
57	/**
58	 * @author Vitaliy Fedoriv
59	 */
60	
61	@RestController
62	@CrossOrigin(exposedHeaders = "errors, content-type")
63	@RequestMapping("/api")
64	public class OwnerRestControllerV1 implements OwnersApi {
65	
66	    /**
67	     * Dedicated audit logger recording successful owner creations.
68	     */
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
120	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
121	            return new ResponseEntity<>(HttpStatus.CONFLICT);
122	        }
123	        if (owner.getRegistrationDate() == null) {
124	            owner.setRegistrationDate(LocalDate.now());
125	        }
126	        if (hasReachedDailyRegistrationLimit(owner.getRegistrationDate())) {
127	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
128	        }
129	        if (hasReachedCityCapacity(owner.getCity())) {
130	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	        }
132	        owner.setNamesakeCount(countNamesakes(owner.getLastName()));
133	        owner.setSharesHousehold(sharesHousehold(owner));
134	        owner.setLocality(determineLocality(owner.getCity()));
135	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
136	        owner.setMembershipTier(determineMembershipTier(owner.getMembershipNumber()));
137	        owner.setCity(normalizeCity(owner.getCity()));
138	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
139	        this.clinicService.saveOwner(owner);
140	        AUDIT.info("Owner created by user={} ownerId={} membershipNumber={}",
141	            currentUsername(), owner.getId(), owner.getMembershipNumber());
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    /**
149	     * Returns the name of the currently authenticated user, or {@code "anonymous"}
150	     * when no authentication is present in the security context.
151	     */
152	    private static String currentUsername() {
153	        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();
154	        return authentication != null ? authentication.getName() : "anonymous";
155	    }
156	
157	    /**
158	     * The maximum number of owners that may be registered on any single day.
159	     */
160	    private static final long MAX_OWNERS_PER_DAY = 20;
161	
162	    /**
163	     * Determines whether the number of owners already registered on the given date has reached the
164	     * daily registration limit. When 20 owners share the same registration date, no further owner may
165	     * be created for that day.
166	     */
167	    private boolean hasReachedDailyRegistrationLimit(LocalDate registrationDate) {
168	        long ownersRegisteredOnDate = this.clinicService.findAllOwners().stream()
169	            .filter(existing -> Objects.equals(existing.getRegistrationDate(), registrationDate))
170	            .count();
171	        return ownersRegisteredOnDate >= MAX_OWNERS_PER_DAY;
172	    }
173	
174	    /**
175	     * The maximum number of owners that may share a single city.
176	     */
177	    private static final long MAX_OWNERS_PER_CITY = 8;
178	
179	    /**
180	     * Determines whether the given city has already reached its capacity of owners. When a city
181	     * already contains 8 owners, no further owner may be created in that city. Cities are matched
182	     * ignoring letter case.
183	     */
184	    private boolean hasReachedCityCapacity(String city) {
185	        if (city == null) {
186	            return false;
187	        }
188	        long ownersInCity = this.clinicService.findAllOwners().stream()
189	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
190	            .count();
191	        return ownersInCity >= MAX_OWNERS_PER_CITY;
192	    }
193	
194	    /**
195	     * Counts how many existing owners share the given last name at the moment a new owner is
196	     * created. The newly created owner itself is not yet persisted and so is never included in
197	     * the count. Last names are compared exactly.
198	     */
199	    private int countNamesakes(String lastName) {
200	        if (lastName == null) {
201	            return 0;
202	        }
203	        return (int) this.clinicService.findAllOwners().stream()
204	            .filter(existing -> Objects.equals(existing.getLastName(), lastName))
205	            .count();
206	    }
207	
208	    /**
209	     * Determines whether the given owner shares a household with an owner that already exists,
210	     * meaning another owner already has the same address and city. Addresses and cities are
211	     * compared ignoring letter case and any surrounding or repeated whitespace. The newly created
212	     * owner itself is not yet persisted and so is never matched against.
213	     */
214	    private boolean sharesHousehold(Owner owner) {
215	        String address = normalize(owner.getAddress());
216	        String city = normalize(owner.getCity());
217	        if (address == null || city == null) {
218	            return false;
219	        }
220	        return this.clinicService.findAllOwners().stream()
221	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
222	                && Objects.equals(normalize(existing.getCity()), city));
223	    }
224	
225	    /**
226	     * Determines the locality of a newly created owner based on its city. The owner is 'local'
227	     * when its city is the single most common city among the owners that already exist at the
228	     * moment of creation; otherwise it is 'remote'. When no city is the sole most common one
229	     * (for example because two cities are tied for the highest count, or no owners yet exist),
230	     * every newly created owner is 'remote'. Cities are compared ignoring letter case.
231	     */
232	    private String determineLocality(String city) {
233	        if (city == null) {
234	            return "REMOTE";
235	        }
236	        Map<String, Long> cityCounts = this.clinicService.findAllOwners().stream()
237	            .map(Owner::getCity)
238	            .filter(existing -> existing != null)
239	            .collect(Collectors.groupingBy(existing -> existing.toLowerCase(Locale.ROOT), Collectors.counting()));
240	        if (cityCounts.isEmpty()) {
241	            return "REMOTE";
242	        }
243	        long maxCount = Collections.max(cityCounts.values());
244	        List<String> mostCommonCities = cityCounts.entrySet().stream()
245	            .filter(entry -> entry.getValue() == maxCount)
246	            .map(Map.Entry::getKey)
247	            .toList();
248	        if (mostCommonCities.size() != 1) {
249	            return "REMOTE";
250	        }
251	        return mostCommonCities.get(0).equals(city.toLowerCase(Locale.ROOT)) ? "LOCAL" : "REMOTE";
252	    }
253	
254	    /**
255	     * The number of owners that receive the founding membership tier. The first 100 owners ever
256	     * created are 'FOUNDING'; every owner created thereafter is 'STANDARD'.
257	     */
258	    private static final int FOUNDING_TIER_LIMIT = 100;
259	
260	    /**
261	     * Determines the membership tier for a newly created owner based on its sequential membership
262	     * number. Owners whose membership number is within the first {@value #FOUNDING_TIER_LIMIT} are
263	     * 'FOUNDING'; all later owners are 'STANDARD'.
264	     */
265	    private String determineMembershipTier(int membershipNumber) {
266	        return membershipNumber <= FOUNDING_TIER_LIMIT ? "FOUNDING" : "STANDARD";
267	    }
268	
269	    /**
270	     * Generates the customer code for a newly created owner. The code is formatted as
271	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
272	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
273	     * Cities are matched ignoring letter case.
274	     */
275	    private String generateCustomerCode(String city) {
276	        long ownersInCity = this.clinicService.findAllOwners().stream()
277	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
278	            .count();
279	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
280	    }
281	
282	    /**
283	     * Normalizes the city of a newly created owner. If an owner already exists in the same
284	     * city (matched ignoring letter case), that existing owner's exact spelling of the city is
285	     * reused so that all owners in a city share one canonical spelling. Otherwise the supplied
286	     * city is title-cased, capitalizing the first letter of each whitespace-separated word and
287	     * lowercasing the rest, so for example "new york" becomes "New York".
288	     */
289	    private String normalizeCity(String city) {
290	        if (city == null) {
291	            return null;
292	        }
293	        return this.clinicService.findAllOwners().stream()
294	            .map(Owner::getCity)
295	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
296	            .findFirst()
297	            .orElseGet(() -> toTitleCase(city));
298	    }
299	
300	    /**
301	     * Title-cases the given value by capitalizing the first letter of each whitespace-separated
302	     * word and lowercasing the remaining letters, preserving the original whitespace: for example
303	     * "new  YORK" becomes "New  York".
304	     */
305	    private static String toTitleCase(String value) {
306	        StringBuilder result = new StringBuilder(value.length());
307	        boolean capitalizeNext = true;
308	        for (int i = 0; i < value.length(); i++) {
309	            char c = value.charAt(i);
310	            if (Character.isWhitespace(c)) {
311	                capitalizeNext = true;
312	                result.append(c);
313	            } else if (capitalizeNext) {
314	                result.append(Character.toTitleCase(c));
315	                capitalizeNext = false;
316	            } else {
317	                result.append(Character.toLowerCase(c));
318	            }
319	        }
320	        return result.toString();
321	    }
322	
323	    /**
324	     * Determines whether an owner already exists that uses the same telephone number
325	     * as the given one. Telephone numbers must be unique across all owners. The
326	     * comparison ignores letter case and any surrounding or repeated whitespace.
327	     */
328	    private boolean isDuplicateOwner(Owner owner) {
329	        String telephone = normalizeTelephone(owner.getTelephone());
330	        return this.clinicService.findAllOwners().stream()
331	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
332	    }
333	
334	    /**
335	     * Normalizes a telephone number for storage and comparison by stripping spaces, dashes
336	     * and parentheses so that only digits remain: for example "(613) 555-0100" becomes
337	     * "6135550100". This lets differently punctuated forms of the same number be treated as
338	     * equal for the uniqueness check and stored in a single canonical form.
339	     */
340	    private static String normalizeTelephone(String telephone) {
341	        if (telephone == null) {
342	            return null;
343	        }
344	        return telephone.replaceAll("[\\s()-]", "");
345	    }
346	
347	    /**
348	     * Determines whether another owner already uses the same email address as the given one.
349	     * Email addresses, when supplied, must be unique across all owners. An owner without an
350	     * email address is never considered a duplicate. The comparison ignores letter case and
351	     * any surrounding or repeated whitespace.
352	     */
353	    private boolean isDuplicateEmail(Owner owner) {
354	        String email = normalize(owner.getEmail());
355	        if (email == null || email.isEmpty()) {
356	            return false;
357	        }
358	        return this.clinicService.findAllOwners().stream()
359	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
360	    }
361	
362	    /**
363	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
364	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
365	     * and "John Smith" normalize to the same key and so count as the same person.
366	     */
367	    private static String normalize(String value) {
368	        if (value == null) {
369	            return null;
370	        }
371	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
372	    }
373	
374	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
375	    @Override
376	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
377	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
378	        if (currentOwner == null) {
379	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
380	        }
381	        currentOwner.setAddress(ownerFieldsDto.getAddress());
382	        currentOwner.setCity(ownerFieldsDto.getCity());
383	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
384	        currentOwner.setLastName(ownerFieldsDto.getLastName());
385	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
386	        this.clinicService.saveOwner(currentOwner);
387	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
388	    }
389	
390	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
391	    @Transactional
392	    @Override
393	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
394	        Owner owner = this.clinicService.findOwnerById(ownerId);
395	        if (owner == null) {
396	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
397	        }
398	        this.clinicService.deleteOwner(owner);
399	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
400	    }
401	
402	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
403	    @Override
404	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
405	        Owner owner = this.clinicService.findOwnerById(ownerId);
406	        if (owner == null) {
407	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
408	        }
409	        HttpHeaders headers = new HttpHeaders();
410	        Pet pet = petMapper.toPet(petFieldsDto);
411	        owner.setId(ownerId);
412	        pet.setOwner(owner);
413	        pet.getType().setName(null);
414	        this.clinicService.savePet(pet);
415	        PetDto petDto = petMapper.toPetDto(pet);
416	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
417	            .buildAndExpand(pet.getId()).toUri());
418	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
419	    }
420	
421	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
422	    @Override
423	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
424	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
425	        if (currentOwner != null) {
426	            Pet currentPet = this.clinicService.findPetById(petId);
427	            if (currentPet != null) {
428	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
429	                currentPet.setName(petFieldsDto.getName());
430	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
431	                this.clinicService.savePet(currentPet);
432	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
433	            }
434	        }
435	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
436	    }
437	
438	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
439	    @Override
440	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
441	        HttpHeaders headers = new HttpHeaders();
442	        Visit visit = visitMapper.toVisit(visitFieldsDto);
443	        Pet pet = new Pet();
444	        pet.setId(petId);
445	        visit.setPet(pet);
446	        this.clinicService.saveVisit(visit);
447	        VisitDto visitDto = visitMapper.toVisitDto(visit);
448	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
449	            .buildAndExpand(visit.getId()).toUri());
450	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
451	    }
452	
453	
454	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
455	    @Override
456	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
457	        Owner owner = this.clinicService.findOwnerById(ownerId);
458	        if (owner != null) {
459	            Pet pet = owner.getPet(petId);
460	            if (pet != null) {
461	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
462	            }
463	        }
464	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
465	    }
466	}
